#!/usr/bin/env python3
"""Publish the deterministic Phase 45 candidate package and remove this temporary publisher."""
from __future__ import annotations
import base64
import json
import os
import subprocess
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PAYLOAD = """"""
FILES = ['release/phase-45-offline-consequence-plan-review-response-intake-envelope-validation-execution-authorization-decision-candidate-population-readiness.json', 'reports/phase-45-offline-consequence-plan-review-response-intake-envelope-validation-execution-authorization-decision-candidate-population-readiness.md', 'scripts/generate_phase45_offline_consequence_plan_review_response_intake_envelope_validation_execution_authorization_decision_candidate_population_readiness.py', 'scripts/validate_phase45_offline_consequence_plan_review_response_intake_envelope_validation_execution_authorization_decision_candidate_population_readiness.py', 'software/tests/test_phase45_offline_consequence_plan_review_response_intake_envelope_validation_execution_authorization_decision_candidate_population_readiness.py']

def run(*args: str) -> None:
    subprocess.run(args, cwd=ROOT, check=True)

def main() -> int:
    decoded = zlib.decompress(base64.b64decode(PAYLOAD))
    files = json.loads(decoded.decode("utf-8"))
    if sorted(files) != sorted(FILES):
        raise SystemExit("Phase 45 publisher payload path drift")
    for relative, content in files.items():
        path = ROOT / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
    run("python3", "-m", "py_compile",
        "scripts/generate_phase45_offline_consequence_plan_review_response_intake_envelope_validation_execution_authorization_decision_candidate_population_readiness.py",
        "scripts/validate_phase45_offline_consequence_plan_review_response_intake_envelope_validation_execution_authorization_decision_candidate_population_readiness.py")
    run("python3", "scripts/generate_phase45_offline_consequence_plan_review_response_intake_envelope_validation_execution_authorization_decision_candidate_population_readiness.py", "--check")
    run("python3", "scripts/validate_phase45_offline_consequence_plan_review_response_intake_envelope_validation_execution_authorization_decision_candidate_population_readiness.py")
    run("python3", "-m", "unittest", "software.tests.test_phase45_offline_consequence_plan_review_response_intake_envelope_validation_execution_authorization_decision_candidate_population_readiness", "-v")
    run("python3", "scripts/validate_phase44_postmerge_record.py")
    (ROOT / "scripts/publish_phase45_candidate.py").unlink()
    run("git", "config", "user.name", "github-actions[bot]")
    run("git", "config", "user.email", "41898282+github-actions[bot]@users.noreply.github.com")
    run("git", "add", *FILES, "scripts/publish_phase45_candidate.py")
    run("git", "diff", "--cached", "--check")
    run("git", "commit", "-m", "Add Phase 45 candidate population readiness")
    run("git", "push", "origin", "HEAD")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
